import Notice from "@/components/Notice.vue";
export default {
  name: "Announcement",
  components: [Notice],
  props: {
    modelValue: {
      type: Boolean,
      default: false
    },
    content: {
      type: String,
      default: ""
    },
    width: {
      type: String,
      default: "400px"
    }
  },
  emits: ["close"],
  computed: {
    dialogVisible: {
      get() {
        return this.modelValue;
      }
    }
  },
  methods: {
    handleClose() {
      this.$emit("close");
    }
  }
};